package com.bank.voucher;

import java.util.logging.*;

public class RangeClosedDemo {
    private static final Logger log = Logger.getLogger("Voucher");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        VoucherService service = new VoucherService();
        int total = service.sumFirst(100);
        log.info(() -> "Sum of first 100 = " + total);   // 5050
    }
}

// ─── Would be in service/VoucherService.java ───
class VoucherService {
    int sumFirst(int n) {
        return java.util.stream.IntStream.rangeClosed(1, n)  // 1..n inclusive
            .sum();                                           // int total
    }
    // overflow-safe variant for large n
    long sumFirstLong(int n) {
        return java.util.stream.IntStream.rangeClosed(1, n)
            .asLongStream()                                   // widen to avoid overflow
            .sum();
    }
}
